    codeSnippet: '// Kotlin class: no outer reference (safe)\nclass MyActivity : Activity() {\n    class MyCallback : Callback { } // No outer ref\n}\n\n// Kotlin inner class: holds outer reference (potential leak)\nclass MyActivity : Activity() {\n    inner class MyCallback : Callback { } // Holds MyActivity ref\n}\n\n// Lambda capture: holds outer reference (potential leak)\nclass MyActivity : Activity() {\n    fun start() {\n        handler.postDelayed({\n            textView.text = "Done" // captures this@MyActivity\n        }, 60_000)\n    }\n}',
