    codeSnippet: '// Data class used with Gson\ndata class User(val name: String, val email: String)\n// After R8 without rules: class a(val b: String, val c: String)\n// Gson looks for "name" field but finds "b" -> fails\n\n// proguard-rules.pro\n-keep class com.example.model.** {\n    <fields>;\n    <init>(...);\n}\n\n// Better: use @SerializedName (Gson) or @Json (Moshi)\ndata class User(\n    @SerializedName("name") val name: String,\n    @SerializedName("email") val email: String\n)\n// R8-safe: annotation preserves the mapping',
