    codeSnippet: '// Complex state class\ndata class FilterState(\n    val categories: Set<String>,\n    val priceRange: IntRange,\n    val sortBy: SortOrder\n)\n\nval FilterStateSaver = run {\n    val categoriesKey = "categories"\n    val minPriceKey = "minPrice"\n    val maxPriceKey = "maxPrice"\n    val sortKey = "sort"\n    mapSaver(\n        save = { state ->\n            mapOf(\n                categoriesKey to ArrayList(state.categories),\n                minPriceKey to state.priceRange.first,\n                maxPriceKey to state.priceRange.last,\n                sortKey to state.sortBy.name\n            )\n        },\n        restore = { map ->\n            FilterState(\n                categories = (map[categoriesKey] as List<String>).toSet(),\n                priceRange = (map[minPriceKey] as Int)..(map[maxPriceKey] as Int),\n                sortBy = SortOrder.valueOf(map[sortKey] as String)\n            )\n        }\n    )\n}\n\n// Usage:\nvar filter by rememberSaveable(stateSaver = FilterStateSaver) {\n    mutableStateOf(FilterState.DEFAULT)\n}',
    tags: ['compose', 'saveable', 'saver', 'process-death'],
