    correctAnswer: 0,
    explanation: 'WebView is one of the most notorious sources of memory leaks on Android. It holds references to its context, JavaScript interfaces, and native rendering resources. Even after clearing, some internal references persist. Best practice: create with application context (loses some features), remove from parent in onDestroy, then call destroy().',
    codeSnippet: 'class WebViewActivity : AppCompatActivity() {\n    private var webView: WebView? = null\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        // Create with application context to reduce leak impact\n        webView = WebView(applicationContext).also {\n            binding.container.addView(it)\n            it.loadUrl("https://example.com")\n        }\n    }\n\n    override fun onDestroy() {\n        webView?.let { wv ->\n            // Remove from view hierarchy\n            (wv.parent as? ViewGroup)?.removeView(wv)\n            wv.stopLoading()\n            wv.clearHistory()\n            wv.removeAllViews()\n            wv.destroy()\n        }\n        webView = null\n        super.onDestroy()\n    }\n}',
