    options: ['Baseline Profiles always work; no verification needed', 'Check logcat for profile compilation messages', 'Use Macrobenchmark with StartupMode.COLD comparing compilationMode CompilationMode.None() vs CompilationMode.Partial(baselineProfile). Also verify with adb shell cmd package compile and dumpsys.', 'Check the APK file size decrease'],
    correctAnswer: 2,
    explanation: 'Macrobenchmark provides CompilationMode options: None (fully interpreted), Partial (with baseline profile), and Full (everything AOT). Compare startup timing between modes to measure profile impact. Verify installation with: adb shell dumpsys package <pkg> | grep compile. Force recompilation: adb shell cmd package compile -m speed-profile -f <pkg>.',
    codeSnippet: '@RunWith(AndroidJUnit4::class)\nclass StartupBenchmark {\n    @get:Rule\n    val rule = MacrobenchmarkRule()\n\n    @Test\n    fun startupNoProfile() = benchmark(\n        CompilationMode.None()\n    )\n\n    @Test\n    fun startupWithProfile() = benchmark(\n        CompilationMode.Partial(\n            baselineProfileMode = BaselineProfileMode.Require\n        )\n    )\n\n    private fun benchmark(compilationMode: CompilationMode) {\n        rule.measureRepeated(\n            packageName = PACKAGE,\n            metrics = listOf(StartupTimingMetric()),\n            compilationMode = compilationMode,\n            startupMode = StartupMode.COLD,\n            iterations = 10\n        ) {\n            pressHome()\n            startActivityAndWait()\n        }\n    }\n}\n\n// Typical result: 30-50% faster with profile',
